from pathlib import Path
from datetime import datetime, timezone
import hashlib, json, os, sys

ROOT = Path.cwd().resolve()
LEDGER = ROOT / "knowledge/failure_class_ledger.json"
BACKUP = ROOT / "state/governance/backups/gov1_cycle_b_ledger_before.json"
TEMP = ROOT / "knowledge/.failure_class_ledger.gov1_cycle_b.tmp"
ROLLBACK = ROOT / "knowledge/.failure_class_ledger.gov1_cycle_b.rollback.tmp"

EXPECTED = "bb7a4c07ff3e36b9dfdb86887291a6450a2066a6096585d688175faee3812724"
HASHES = {'AGENTS.md': 'fdae145e26b6cfbd6379e081c1aea323142bd7eea2600c44a7cd6f9443cba591', 'tools/codex_execution_preflight_gate.py': 'c3285dc603d4a165dd4f5e4b1b0a5815e88d9a79fd14ccb0b7ab7f6b1667035c', 'tools/governance_command_runner.py': 'e3aa02280f3c247419a0345c3e5932c428776b578a19d9a450b1b962255d567f', 'config/governance/codex_candidate.schema.json': 'd5138c905d08e5dffa556657e71569f54360d46fcf2d6fc8ec4bdfc91f8bb1f0', 'config/governance/evidence_graph.schema.json': 'a84cfa934b5fa36af423e262f1528daa428d3cfda76f2020597d9edb338ca3ce', 'config/governance/failure_class.schema.json': 'fb8af14f515724fdf93137546547627c2ad91922d4d26a6780b349775e5c3e9e', 'config/governance/gate_report.schema.json': '69397a896278a4419379ef5cb6d4eddea531c7e72176723c369258726a2eaeb8', 'config/governance/root_cause_synonyms.json': '456740ec977ba51bec8983c3bb227c62c8bf602095b1780520e0410ace501bb1', 'tests/test_codex_execution_preflight_gate.py': 'e131c0647a6849a5703ea5c0dd44d64ca4d8a95e855a0802e6034de56295642c'}
WANTED = {"G-001","G-002","G-003","G-004","G-005","G-006"}

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def fresh_write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("xb") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

changed = False

try:
    if sha(LEDGER) != EXPECTED:
        raise RuntimeError("LEDGER_SHA_MISMATCH")

    raw = LEDGER.read_bytes()
    data = json.loads(raw.decode("utf-8"))

    if data.get("version") != 2:
        raise RuntimeError("LEDGER_VERSION_MISMATCH")

    classes = data.get("classes")
    if not isinstance(classes, list) or len(classes) != 6:
        raise RuntimeError("CLASS_SET_MISMATCH")

    found = {}

    for item in classes:
        hits = WANTED & set(item.get("aliases", []))
        if len(hits) != 1:
            raise RuntimeError("ALIAS_SET_MISMATCH")

        gid = next(iter(hits))
        controls = item.get("required_prevention_controls")

        if gid in found or item.get("status") != "REOPENED":
            raise RuntimeError(f"{gid}_STATE_MISMATCH")

        if (
            not isinstance(controls, list)
            or not controls
            or any(not isinstance(x, str) or not x for x in controls)
        ):
            raise RuntimeError(f"{gid}_CONTROL_MISMATCH")

        found[gid] = item

    if set(found) != WANTED:
        raise RuntimeError("WANTED_SET_MISMATCH")

    if BACKUP.exists() or TEMP.exists() or ROLLBACK.exists():
        raise RuntimeError("FRESH_PATH_REQUIRED")

    fresh_write(BACKUP, raw)

    if sha(BACKUP) != EXPECTED:
        raise RuntimeError("BACKUP_SHA_MISMATCH")

    closed_at = datetime.now(timezone.utc).isoformat()

    for item in found.values():
        controls = list(item["required_prevention_controls"])

        item["status"] = "CLOSED"
        item["closure_evidence"] = {
            "validator_version": "1.1.0",
            "artifact_hashes": dict(HASHES),
            "closed_at_utc": closed_at,
            "time_window": "until_governance_artifact_change",
            "required_prevention_controls": controls,
            "test_run_id": "gov1-v4-functional-85tests-20260905",
            "ledger_version": 3,
        }

    data["version"] = 3

    fresh_write(
        TEMP,
        (json.dumps(data, ensure_ascii=False, indent=2) + "\n").encode("utf-8"),
    )

    os.replace(TEMP, LEDGER)
    changed = True

    check = json.loads(LEDGER.read_text(encoding="utf-8"))

    if check.get("version") != 3:
        raise RuntimeError("POST_VERSION_MISMATCH")

    seen = set()

    for item in check.get("classes", []):
        hits = WANTED & set(item.get("aliases", []))
        if len(hits) != 1:
            raise RuntimeError("POST_ALIAS_SET_MISMATCH")

        gid = next(iter(hits))
        ev = item.get("closure_evidence", {})
        controls = item.get("required_prevention_controls")

        if item.get("status") != "CLOSED":
            raise RuntimeError(f"{gid}_POST_STATUS_MISMATCH")

        if ev.get("validator_version") != "1.1.0":
            raise RuntimeError(f"{gid}_POST_VALIDATOR_MISMATCH")

        if ev.get("artifact_hashes") != HASHES:
            raise RuntimeError(f"{gid}_POST_ARTIFACT_BIND_MISMATCH")

        if ev.get("required_prevention_controls") != controls:
            raise RuntimeError(f"{gid}_POST_CONTROL_BIND_MISMATCH")

        if ev.get("time_window") != "until_governance_artifact_change":
            raise RuntimeError(f"{gid}_POST_WINDOW_MISMATCH")

        if ev.get("ledger_version") != 3:
            raise RuntimeError(f"{gid}_POST_LEDGER_BIND_MISMATCH")

        seen.add(gid)

    if seen != WANTED:
        raise RuntimeError("POST_CLASS_SET_MISMATCH")

    print("CYCLE_B_MUTATION:PASS")
    print("LEDGER_VERSION=3")
    print("G001_G006_STATUS=CLOSED")

except Exception as error:
    if changed:
        try:
            fresh_write(ROLLBACK, BACKUP.read_bytes())
            os.replace(ROLLBACK, LEDGER)

            if sha(LEDGER) != EXPECTED:
                raise RuntimeError("ROLLBACK_SHA_MISMATCH")

            print("ROLLBACK:PASS", file=sys.stderr)

        except Exception as rollback_error:
            print(
                f"ROLLBACK:FAIL:{type(rollback_error).__name__}",
                file=sys.stderr,
            )

    print(
        f"CYCLE_B_MUTATION:FAIL:{type(error).__name__}:{error}",
        file=sys.stderr,
    )
    sys.exit(1)
